@GetMapping("/{id}")
Mono<ResponseEntity<Book>> jedna(@PathVariable String id) {
    return repository.findById(id)
        .map(ResponseEntity::ok)
        .defaultIfEmpty(ResponseEntity.notFound().build());
}

@PostMapping
Mono<ResponseEntity<Book>> dodaj(@Valid @RequestBody Mono<Book> body) {
    return body
        .flatMap(repository::save)
        .map(saved -> ResponseEntity.status(HttpStatus.CREATED).body(saved));
}

@GetMapping(value = "/events", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
Flux<Book> events() {
    return repository.changes(); // źródło reaktywne, nieblokujące
}

@PostMapping
Mono<Void> dodaj(@RequestBody Mono<Book> body) {
    body.flatMap(repository::save).subscribe(); // błąd
    return Mono.empty();
}

@PostMapping
Mono<Void> dodaj(@RequestBody Mono<Book> body) {
    return body.flatMap(repository::save).then();
}
